"""Measured landmarks in preserved orthographic drawings, not procedural templates.
Coordinates refer to preserved full raster pixels. Side z is engine shaft up;
plan u is nose-to-tail. Thin hidden root sections are interpolated explicitly.
Run from repository root. This does not read game or external mesh geometry.
"""
import json
from pathlib import Path
ROOT=Path('assets/aircraft')
def round_tree(v):
 if isinstance(v,float):return round(v,5)
 if isinstance(v,list):return [round_tree(x) for x in v]
 if isinstance(v,dict):return {k:round_tree(x) for k,x in v.items()}
 return v

def make(id,L,S,ref,side,plan,raw,cowling,prop,gear,extras):
 sx0,sx1,shaft=side; px0,px1,center,halfspan=plan
 su=lambda x:(x-sx0)/(sx1-sx0)
 pu=lambda x:(x-px0)/(px1-px0)
 sm=L/(sx1-sx0);pm=S/(2*halfspan)
 spec={'schemaVersion':1,'id':id,'reference':ref,'fuselage':[[su(x),w*pm,(shaft-bot)*sm,(shaft-top)*sm] for x,w,bot,top in raw['fuselage']],
 'wing':[[d/halfspan,pu(le),pu(te),z] for d,le,te,z in raw['wing']],
 'horizontalTail':[[d/raw['tailHalfSpanPx'],pu(le),pu(te),z] for d,le,te,z in raw['horizontalTail']],
 'tailSpan':2*raw['tailHalfSpanPx']*pm,
 'fin':[[su(x),(shaft-y)*sm] for x,y in raw['fin']],
 'canopy':[[su(x),w*pm,(shaft-base)*sm,(shaft-top)*sm] for x,w,base,top in raw['canopy']],
 'cowling':cowling,'propeller':prop,'gear':gear,'extras':extras}
 ref['registration']={'side':{'boundsPx':[sx0,0,sx1,330],'nosePx':[sx0,shaft],'tailPx':[sx1,shaft],'shaftYPx':shaft,'metersPerPixel':sm},'plan':{'noseXPx':px0,'tailXPx':px1,'centerYPx':center,'halfSpanPx':halfspan,'spanMetersPerPixel':pm},'rawLandmarksPx':raw,'method':'Manual visual landmark measurement of preserved orthographic raster; each view independently registered to catalog length/span. Fuselage cross sections use elliptical interpolation between side and plan envelopes. Hidden wing roots and canopy bases are interpolated; a drawing is not a manufacturing loft.'}
 out=ROOT/'shapes'/f'{id}.json';out.write_text(json.dumps(round_tree(spec),indent=2)+'\n');print(out)

